// Helper badge color per subject
export const getSubjectBadge = (subject: string) => {
  if (subject.includes("Physics")) return "bg-blue-50 text-[#0056D2] border-blue-200";
  if (subject.includes("Biology")) return "bg-emerald-50 text-emerald-700 border-emerald-200";
  if (subject.includes("Co-ordinated") || subject.includes("Science") || subject.includes("Chemistry")) return "bg-amber-50 text-amber-700 border-amber-200";
  return "bg-gray-50 text-gray-700 border-gray-200";
};

export const getSubjectGradient = (subject: string) => {
  if (subject.includes("Physics")) return "from-[#00419E] to-[#002663]";
  if (subject.includes("Biology")) return "from-emerald-800 to-teal-900";
  if (subject.includes("Co-ordinated") || subject.includes("Science") || subject.includes("Chemistry")) return "from-amber-800 to-orange-950";
  return "from-[#0056D2] to-[#003B93]";
};

export const getSubjectIconComponent = (subject: string) => {
  if (subject.includes("Physics")) return Atom;
  if (subject.includes("Biology")) return Dna;
  if (subject.includes("Co-ordinated") || subject.includes("Science") || subject.includes("Chemistry")) return Beaker;
  return Layers;
};
